import {CLASSES,REALMS,ENCOUNTERS,ECHOES,ACTIONS,createRun,loadRun,realmOf,foeOf,stats,maxHealth,enter,intent,actionMeta,blocked,act,forecast,claim,shop,purchase,travel} from './adventure-engine.mjs';
import {prepareEnemyTexture} from './sprite-texture.mjs';
const app=document.querySelector('#app'),KEY='arena-heir-crownlands-v3';
let state=null,saved=null,view='start',selected='miri',busy=false,notice='',sound=false,audio;
try{saved=loadRun(localStorage.getItem(KEY)||localStorage.getItem('arena-heir-v1'));sound=localStorage.getItem('arena-heir-sound')==='on';}catch{}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const char=id=>`<span class="hero-art hero-${id}" aria-hidden="true"></span>`;
const art=f=>`<span class="enemy-art" style="--col:${f.art%3};--row:${Math.floor(f.art/3)}" aria-hidden="true"></span>`;
const theme=()=>`--realm:${Math.floor(state.round/4)};--accent:${realmOf(state).color};--realm-image:url('assets/crownlands/${realmOf(state).id}.webp')`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));saved=structuredClone(state);}catch{notice='Saving is unavailable. Keep this tab open to continue.';}}
function beep(kind){if(!sound)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type=kind==='hit'?'triangle':'sine';const t=audio.currentTime;o.frequency.setValueAtTime(kind==='win'?523:330,t);o.frequency.exponentialRampToValueAtTime(kind==='win'?1046:kind==='spell'?750:75,t+.16);g.gain.setValueAtTime(.035,t);g.gain.exponentialRampToValueAtTime(.001,t+.22);o.start(t);o.stop(t+.23);}catch{}}
function header(){return `<header class="topbar"><button class="wordmark" data-do="home" aria-label="Arena Heir home">ARENA<span>HEIR</span><small>CROWN OF ECHOES</small></button><nav aria-label="Game controls"><button data-do="help" aria-label="How to play">?</button><button data-do="sound" aria-pressed="${sound}" aria-label="Sound ${sound?'on':'off'}">♫ <span>${sound?'On':'Off'}</span></button>${state?'<button data-do="exit">Save & exit</button>':''}</nav></header>`;}
function render(){app.innerHTML=`<div class="game">${header()}${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}${view==='start'?opening():view==='choose'?choose():view==='shop'?storeScreen():state.stage==='map'?world():state.stage==='battle'?battle():state.stage==='reward'?rewards():state.stage==='camp'?camp():ending()}<footer>Progress stays on this device <span>✦</span> No real-money purchases</footer></div>`;}
function opening(){return `<section class="opening"><div class="opening-title"><span class="eyebrow">THE CROWNLANDS AWAIT</span><h1>Small heroes.<br><em>Unbroken spirit.</em></h1><p>Three realms. Three masters.<br>One crown worth fighting for.</p></div><div class="opening-actions">${saved&&!['won','lost'].includes(saved.stage)?`<button class="primary" data-do="resume">Continue journey →</button><small>${esc(saved.name)} · ${realmOf(saved).name} · Battle ${saved.round%4+1}/4</small><button class="secondary" data-do="choose">Choose a new hero</button>`:'<button class="primary" data-do="choose">Choose your hero →</button><small>A tactical adventure. Play at your own pace.</small>'}</div></section>`;}
function choose(){return `<section class="selection"><div class="section-title"><span class="eyebrow">THREE WAYS TO DEFY A CROWN</span><h1>Who will you become?</h1><p>Same road. A very different way to fight.</p></div><div class="hero-cards">${Object.entries(CLASSES).map(([id,h])=>`<button class="hero-card ${selected===id?'selected':''}" data-hero="${id}" aria-pressed="${selected===id}" style="--hero:${h.color}"><div class="hero-portrait">${char(id)}</div><div class="hero-bio"><span class="eyebrow">${h.role}</span><h2>${h.name}</h2><p>${h.desc}</p><span class="trait">${h.icon} ${h.passive}</span><span class="hero-hp">♥ ${h.hp} HP</span></div></button>`).join('')}</div><div class="begin-panel"><label>Name your hero<input id="hero-name" maxlength="18" value="${CLASSES[selected].name}" autocomplete="off"></label><button class="primary" data-do="begin">Enter Mosswhisper →</button></div></section>`;}
function wallet(){return `<div class="wallet"><span>♥ <b>${state.hp}</b>/${maxHealth(state)}</span><span class="coins">✦ <b>${state.gold}</b> coins</span></div>`;}
function journeyNav(){const r=Math.floor(state.round/4);return `<div class="realm-tabs" aria-label="Realm progress">${REALMS.map((x,i)=>`<div class="${i===r?'active':i<r?'complete':'locked'}"><span>${i<r?'✓':i===r?'✦':'◇'}</span><b>${x.name}</b><small>${i<r?'Cleared':i===r?'Current realm':'Locked'}</small></div>`).join('')}</div>`;}
function world(){const realm=realmOf(state),foe=foeOf(state),start=Math.floor(state.round/4)*4;return `<section class="world" style="${theme()}">${journeyNav()}<div class="realm-banner realm-bg"><div class="realm-heading"><span class="eyebrow">REALM ${Math.floor(state.round/4)+1} OF 3 · ${realm.label}</span><h1>${realm.name}</h1><p>${realm.subtitle}</p></div><div class="realm-traveler">${char(state.hero)}</div><span class="landmark">${foe.master?'THE MASTER IS WAITING':'FOLLOW THE LAUREL ROAD'}</span></div><div class="route" aria-label="Four battles in this realm">${ENCOUNTERS.slice(start,start+4).map(f=>`<div class="route-stop ${f.index===state.round?'current':f.index<state.round?'complete':'locked'} ${f.master?'master':''}"><span>${f.index<state.round?'✓':f.master?'♛':f.index%4+1}</span><b>${f.master?'MASTER':`BATTLE ${f.index%4+1}`}</b><small>${f.name}</small></div>`).join('')}</div><div class="next-battle"><div><span class="eyebrow">NEXT CHALLENGER</span><h2>${foe.name}</h2><p>${realm.rule}</p><small class="road-note">${esc(state.log[0]||'')}</small></div><div class="journey-cta">${wallet()}<button class="primary" data-do="fight">${foe.master?'Challenge the master':'Enter battle'} ⚔</button><button class="secondary" data-do="shop">Visit equipment shop</button></div></div>${state.legacy?'<p class="legacy-note">Earlier progress imported. Coins and upgrades are preserved; unfinished battles restart in the new world.</p>':''}</section>`;}
function healthCard(enemy=false){const hp=enemy?state.foeHp:state.hp,max=enemy?foeOf(state).hp:maxHealth(state);return `<div class="health-card ${enemy?'rival-health':'player-health'}"><div><strong>${esc(enemy?foeOf(state).name:state.name)}</strong><span class="hp-value">${hp}/${max}</span></div><div class="health-track" role="progressbar" aria-label="${enemy?'Enemy':'Your'} health" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${hp}"><i style="width:${hp/max*100}%"></i></div><small>${enemy?foeOf(state).master?'REALM MASTER':realmOf(state).label:`${CLASSES[state.hero].role} · ${stats(state).armor} armor`}</small></div>`;}
function intentCopy(){const p=intent(state);return {strike:`Strike · ${p.amount} damage`,heavy:`Heavy blow · ${p.amount} damage`,double:`Twin strike · 2 × ${p.amount} damage`,drain:`Life drain · ${p.amount} damage`,windup:'Winding up · A heavy blow follows',ward:`Shield raised · Blocks ${p.amount} damage`}[p.type];}
function actionButton(id){const m=actionMeta(state,id),why=blocked(state,id),f=why?null:forecast(state,id);const detail=why?esc(why):f.won?'Finishing blow':f.interrupt?`${f.dealt} damage · INTERRUPT`:f.dealt?`${f.dealt} damage`:id==='guard'?`Block ${CLASSES[state.hero].guard}`:id==='rest'?'+3 energy':id==='dodge'?'Evade first hit':`+${f.heal} HP · Block 25`;return `<button class="action action-${id}" data-action="${id}" ${why?'disabled':''} aria-label="${esc(m.name+'. '+m.desc+(f?` Deal ${f.dealt}. Take ${f.taken}.`:''))}"><span class="action-glyph">${m.icon}</span><span class="action-name">${m.name}</span><small>${detail}</small>${!why?`<span class="risk ${f.taken?'danger':'safe'}">${f.taken?`Receive ${f.taken}`:'No hit taken'}</span>`:''}<span class="cost">${id==='ultimate'?'100 FOCUS':m.cost?`${m.cost} ⚡`:'FREE'}</span></button>`;}
function battle(){const foe=foeOf(state),p=intent(state);return `<section class="battle" style="${theme()}"><div class="battle-top"><span>${realmOf(state).name} <b>· ${foe.master?'MASTER':`${state.round%4+1}/4`}</b></span><span class="coins">✦ ${state.gold}</span></div><div class="health-row">${healthCard()}${healthCard(true)}</div><div class="arena realm-bg ${foe.master?'boss-arena':''}"><div class="battle-actor player" data-side="player">${char(state.hero)}</div><div class="battle-actor enemy" data-side="enemy">${art(foe)}</div><div class="battle-effects" aria-hidden="true"></div><div class="battle-announcement" role="status" aria-live="polite">${p.enraged?'MASTER AWAKENED':''}</div><div class="fracture" title="Three class skills interrupt the enemy"><span>STANCE</span>${[0,1,2].map(i=>`<i class="${i<state.break?'cracked':''}"></i>`).join('')}<small>${state.break}/3 fractures</small></div></div><div class="intent ${p.type==='heavy'?'danger-intent':''}"><span class="intent-icon">${p.type==='ward'?'⬡':p.type==='windup'?'!':'⚔'}</span><div><small>ENEMY’S NEXT MOVE${p.enraged?' · ENRAGED +20%':''}${p.pressure?' · PRESSURE +'+p.pressure:''}</small><strong>${intentCopy()}</strong></div><span class="turn">TURN ${state.turn+1}</span></div><div class="combat-panel"><div class="resources"><div><span class="eyebrow">YOUR ENERGY</span><div class="energy">${Array.from({length:6},(_,i)=>`<i class="${i<state.energy?'lit':''}"></i>`).join('')}<b>${state.energy}/6</b></div></div><div class="focus-block"><span class="eyebrow">${state.focus===100?'CROWN AWAKENING READY':'CROWN AWAKENING'}</span><div class="focus-track"><i style="width:${state.focus}%"></i></div><small>${state.focus}/100 · ${state.bonus?`Next hit +${state.bonus}`:'Attack or defend to build focus'}</small></div></div><div class="action-grid">${ACTIONS.map(actionButton).join('')}</div>${state.echoes.length?`<div class="echo-row"><span class="eyebrow">CLAIMED ECHOES</span><div>${state.echoes.map(actionButton).join('')}</div></div>`:''}<details class="battle-guide"><summary>Skills, shields & stance breaks</summary><p>Three class skills fracture the enemy’s stance and cancel a turn. Your ultimate also interrupts. Each button forecasts the enemy response.</p><dl>${ACTIONS.map(id=>`<dt>${actionMeta(state,id).name}</dt><dd>${actionMeta(state,id).desc}</dd>`).join('')}</dl></details><div class="last-turn" aria-live="polite">${esc(state.log.join(' '))}</div></div></section>`;}
function rewards(){const foe=foeOf(state),realm=realmOf(state),echo=ECHOES[realm.echo];return `<section class="reward-screen" style="${theme()}"><div class="reward-hero realm-bg"><span class="eyebrow">${foe.master?'REALM CONQUERED':'VICTORY'}</span><h1>${foe.master?realm.name+' is free.':foe.name+' defeated.'}</h1><div class="victory-character">${char(state.hero)}</div><span class="gold-award">✦ +${state.victoryGold} coins earned</span></div><div class="reward-body"><div class="section-title"><span class="eyebrow">MAKE THIS VICTORY YOURS</span><h2>Choose an extra reward</h2><p>Your battle coins are already in your pouch.</p></div><div class="reward-grid"><button class="reward-card" data-reward="gold"><span>✦</span><h3>Champion’s purse</h3><b>+${35+Math.floor(state.round/4)*15} more coins</b><p>Save for stronger weapons and armor.</p></button><button class="reward-card" data-reward="vitality"><span>♥</span><h3>Heart of a hero</h3><b>+8 maximum HP · Heal 18</b><p>A permanent boost for this journey.</p></button><button class="reward-card echo-card" data-reward="echo" ${state.echoes.includes(realm.echo)?'disabled':''}><span>${echo.icon}</span><h3>${echo.name}</h3><b>${state.echoes.includes(realm.echo)?'Already learned':'Learn this realm’s Echo'}</b><p>${echo.desc} ${echo.cost} energy · ${echo.cd}-turn cooldown.</p></button></div></div></section>`;}
function equipment(){return `<div class="equipment-summary"><span>Equipped</span>${['weapon','armor','charm'].map(slot=>`<b>${slot==='weapon'?CLASSES[state.hero].icon:slot==='armor'?'⬡':'❖'} ${slot} <small>${['Starter','Trailbound','Runeforged','Masterwork'][state.equipment[slot]]}</small></b>`).join('')}</div>`;}
function camp(){const master=foeOf(state).master;return `<section class="camp-screen" style="${theme()}"><div class="camp-scenery realm-bg"><div class="camp-character">${char(state.hero)}</div><div><span class="eyebrow">A MOMENT BETWEEN BATTLES</span><h1>${master?'A new realm awaits.':'Sharpen your edge.'}</h1><p>${master?'Crossing into the next realm restores all your health.':'You’ll recover 20 HP when you return to the road.'}</p></div></div><div class="camp-body">${wallet()}${equipment()}<div class="camp-actions"><button class="primary" data-do="shop">Browse equipment shop ✦</button><button class="secondary" data-do="travel">${master?'Travel to '+REALMS[Math.floor(state.round/4)+1].name:'Continue to battle '+(state.round%4+2)} →</button></div></div></section>`;}
function storeScreen(){return `<section class="store"><div class="store-heading"><button class="text-button" data-do="back">← Return to journey</button><span class="eyebrow">THE WANDERING FORGE</span><h1>Better gear.<br>Bigger legends.</h1><p>Buy once, equip immediately. New tiers unlock in each realm.</p>${wallet()}</div>${equipment()}<div class="shop-grid">${shop(state).map(item=>`<div class="shop-item"><span class="item-icon">${item.icon}</span><div><span class="eyebrow">${item.id==='heal'?'CONSUMABLE':['','TRAILBOUND','RUNEFORGED','MASTERWORK'][Math.min(item.level,3)]}</span><h2>${item.name}</h2><p>${item.desc}</p></div><button data-buy="${item.id}" class="${!item.locked&&!item.owned&&state.gold>=item.cost?'primary':'secondary'}" ${item.locked||item.owned||state.gold<item.cost||item.id==='heal'&&state.hp===maxHealth(state)?'disabled':''}>${item.owned?'Fully upgraded':item.locked?'Unlock in '+REALMS[item.level-1]?.name:item.id==='heal'&&state.hp===maxHealth(state)?'Health full':`Buy · ${item.cost} coins`}</button></div>`).join('')}</div><p class="shop-note">Equipment stays with this hero throughout the journey. All purchases use coins earned in battle.</p></section>`;}
function ending(){const won=state.stage==='won';return `<section class="ending"><span class="eyebrow">${won?'THE CROWN HAS FOUND ITS HEIR':'A HERO IS MORE THAN ONE BATTLE'}</span><h1>${won?'Three realms.<br>One unbroken spirit.':'Rise. Learn.<br>Try again.'}</h1><div class="ending-character">${char(state.hero)}</div><p>${won?`${esc(state.name)} has overcome the masters of the Crownlands.`:`${foeOf(state).name} held the line. Read their next move, spend your coins, and come back stronger.`}</p><div class="tally"><b>${won?12:state.round}<small>BATTLES WON</small></b><b>${state.echoes.length}<small>ECHOES LEARNED</small></b><b>${state.gold}<small>COINS</small></b></div><button class="primary" data-do="choose">Choose your next hero →</button></section>`;}
function modal(content){const d=document.createElement('dialog');d.innerHTML=content;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();return d;}
function confirmNew(name){if(saved&&!['won','lost'].includes(saved.stage)){const d=modal('<h2>Begin a new journey?</h2><p>This replaces your current Crownlands save on this device.</p><div class="dialog-actions"><button class="secondary" data-cancel>Keep current journey</button><button class="primary" data-confirm>Start new journey</button></div>');d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{d.close();begin(name);};}else begin(name);}
function begin(name){state=createRun(selected,name);view='game';notice='';persist();render();window.scrollTo(0,0);}
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const wait=ms=>new Promise(r=>setTimeout(r,reduced()?Math.min(ms,35):ms));
async function animate(el,frames,ms){if(!el)return;const a=el.animate(frames,{duration:reduced()?1:ms,easing:'ease-out'});try{await a.finished;}catch{}}
function syncHealth(e){for(const [selector,hp]of [['.player-health',e.hp],['.rival-health',e.foeHp]]){const el=app.querySelector(selector);if(!el)continue;const track=el.querySelector('[role="progressbar"]'),max=Number(track.getAttribute('aria-valuemax'));track.setAttribute('aria-valuenow',hp);track.firstElementChild.style.width=hp/max*100+'%';el.querySelector('.hp-value').textContent=hp+'/'+max;}}
async function playback(events,id){const layer=app.querySelector('.battle-effects'),banner=app.querySelector('.battle-announcement');const say=t=>{if(banner)banner.textContent=t;};
  for(const e of events){
    if(e.type==='hit'){const target=app.querySelector(`.battle-actor.${e.side}`),attacker=app.querySelector(`.battle-actor.${e.side==='player'?'enemy':'player'}`),sign=e.side==='enemy'?1:-1;let lunge=0;say(e.side==='enemy'?actionMeta(state,id).name:'Enemy responds');
      if(e.side==='enemy'&&state.hero!=='tovin'){const bolt=document.createElement('i');bolt.className='projectile '+state.hero;layer.append(bolt);beep('spell');await animate(bolt,[{left:'25%',opacity:0,transform:'scale(.4)'},{left:'48%',opacity:1,transform:'scale(1.2)',offset:.4},{left:'74%',opacity:1,transform:'scale(.6)'}],240);bolt.remove();}
      else{const a=attacker.getBoundingClientRect(),b=target.getBoundingClientRect();lunge=sign*Math.max(16,Math.abs((b.left+b.width/2)-(a.left+a.width/2))-a.width*.5);await animate(attacker,[{transform:'translateX(0)'},{transform:`translateX(${-sign*8}px) rotate(${-sign*4}deg)`,offset:.2},{transform:`translateX(${lunge}px) rotate(${sign*5}deg)`}],260);attacker.style.transform=`translateX(${lunge}px)`;beep('hit');}
      syncHealth(e);const n=document.createElement('b');n.className=`damage-number ${e.side}`;n.textContent=e.amount?'−'+e.amount:'BLOCK';layer.append(n);await Promise.all([animate(n,[{opacity:0,transform:'translateY(10px) scale(.6)'},{opacity:1,transform:'translateY(0) scale(1.1)',offset:.2},{opacity:0,transform:'translateY(-55px) scale(1)'}],470),animate(target,[{filter:'brightness(1)'},{filter:'brightness(2)',transform:`translateX(${sign*8}px)`,offset:.2},{filter:'brightness(1)'}],260)]);n.remove();if(lunge){await animate(attacker,[{transform:`translateX(${lunge}px)`},{transform:'translateX(0)'}],180);attacker.style.transform='';}
    }else if(e.type==='heal'){syncHealth(e);say(`+${e.amount} HP restored`);await wait(170);}
    else if(['break','ultimate','perfect','evade','windup','guard','rest','dodge'].includes(e.type)){say({break:'STANCE BROKEN',ultimate:'CROWN AWAKENING',perfect:'PERFECT GUARD · NEXT HIT +8',evade:'EVADED',windup:'A HEAVY BLOW IS COMING',guard:'GUARD RAISED',rest:'ENERGY RESTORED',dodge:'READY TO EVADE'}[e.type]);if(e.type==='ultimate'){app.querySelector('.arena')?.classList.add('awakening');beep('spell');}await wait(e.type==='ultimate'?420:160);}
    else if(e.type==='victory'){say('VICTORY');beep('win');await wait(450);}else if(e.type==='defeat'){say('THE ROAD REMEMBERS');await wait(350);}
  }
}
app.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled||busy)return;const d=b.dataset;
  if(d.hero){selected=d.hero;render();return;}
  if(d.action){const after=structuredClone(state),events=[];if(!act(after,d.action,events))return;busy=true;notice='';app.querySelectorAll('button').forEach(x=>x.disabled=true);try{await playback(events,d.action);}catch(error){console.error('Playback recovered',error);}finally{state=after;busy=false;persist();render();}return;}
  if(d.reward){if(claim(state,d.reward)){persist();render();window.scrollTo(0,0);}return;}
  if(d.buy){const item=shop(state).find(x=>x.id===d.buy);if(purchase(state,d.buy)){notice=`${item.name} ${d.buy==='heal'?'used. Health restored.':'equipped.'}`;persist();beep('win');render();}return;}
  if(d.do==='choose'){view='choose';selected=state?.hero||'miri';notice='';render();window.scrollTo(0,0);}
  if(d.do==='begin')confirmNew(app.querySelector('#hero-name').value);
  if(d.do==='resume'&&saved){state=structuredClone(saved);view='game';notice='';persist();render();}
  if(d.do==='fight'&&enter(state)){view='game';notice='';persist();render();window.scrollTo(0,0);}
  if(d.do==='shop'){view='shop';notice='';render();window.scrollTo(0,0);}
  if(d.do==='back'){view='game';notice='';render();}
  if(d.do==='travel'&&travel(state)){view='game';notice='';persist();render();window.scrollTo(0,0);}
  if(d.do==='home'||d.do==='exit'){if(state)persist();state=null;view='start';render();window.scrollTo(0,0);}
  if(d.do==='sound'){sound=!sound;try{localStorage.setItem('arena-heir-sound',sound?'on':'off');}catch{}beep('spell');render();}
  if(d.do==='help'){const box=modal('<h2>Your road to the Crown</h2><p>Read the enemy’s next move. Each action shows its damage and the damage you will receive in return.</p><p><b>Break their stance:</b> three class skills interrupt a turn. Guard against small or double hits; evade the first hit of a heavy attack.</p><p><b>Awaken:</b> attacks and active defenses build focus. At 100, unleash an ultimate that stops the enemy’s response.</p><p>Earn coins after every victory, choose an extra reward, and upgrade at the forge. Three battles lead to each realm’s master. Travel heals 20 HP; crossing realms heals fully.</p><p>Keys 1–6 select the main actions. Progress saves after every turn on this device.</p><button class="primary">Back to the adventure</button>');box.querySelector('button').onclick=()=>box.close();}
});
document.addEventListener('keydown',e=>{if(busy||e.repeat||e.target.matches('input,textarea,button')||document.querySelector('dialog[open]')||state?.stage!=='battle')return;const i=Number(e.key)-1;if(i>=0&&i<6){e.preventDefault();app.querySelector(`[data-action="${ACTIONS[i]}"]`)?.click();}});
render();
prepareEnemyTexture().catch(error=>console.error('Enemy texture preparation failed',error));
